detail.command:
set -e
test -d node_modules || npm install
mkdir -p apps/mobile/src/theme apps/mobile/src/api apps/mobile/src/session

cat > apps/mobile/src/theme/index.ts <<'EOF'
export const theme = {
  colors: {
    bg: '#0E1621', surface: '#17212B', bar: '#232E3C', accent: '#2AABEE',
    outgoing: '#2B5278', incoming: '#182533', text: '#FFFFFF', muted: '#8A96A3',
    danger: '#E53935', unread: '#2AABEE', hairline: '#0F1A24',
  },
  typography: {
    title: { fontSize: 17, fontWeight: '600' as const },
    body: { fontSize: 16, fontWeight: '400' as const },
    caption: { fontSize: 13, fontWeight: '400' as const },
    time: { fontSize: 12, fontWeight: '400' as const },
  },
  radii: { bubble: 16, avatar: 24 },
  spacing: { base: 4, xs: 4, sm: 8, md: 12, lg: 16, xl: 24, xxl: 32 },
} as const;
export default theme;
EOF

cat > apps/mobile/src/api/client.ts <<'EOF'
import type { ChatMessage } from '../components/MessageBubble';
import type { MessageStatus } from '../components/Tick';
export async function listMessages(_chatId: string): Promise<ChatMessage[]> { return []; }
export async function sendText(chatId: string, text: string): Promise<ChatMessage> {
  return { id: 'local', chatId, senderId: 'me', type: 'text', text, createdAt: new Date().toISOString(), status: 'sent' };
}
export async function markRead(_chatId: string, _messageId: string): Promise<void> {}
export function connectWs(_handlers: {
  onMessageNew?: (msg: ChatMessage) => void;
  onMessageStatus?: (payload: { messageId: string; status: MessageStatus; chatId?: string }) => void;
}): () => void { return () => {}; }
EOF

cat > apps/mobile/src/session/AuthContext.tsx <<'EOF'
export function useAuth(): { user: { id: string } | null } { return { user: { id: 'me' } }; }
EOF

cat > apps/mobile/src/components/AudioBubble.tsx <<'EOF'
import { Text } from 'react-native';
import type { ChatMessage } from './MessageBubble';
export function AudioBubble(_props: { message: ChatMessage; isMine: boolean }) { return <Text>audio</Text>; }
EOF

cat > apps/mobile/src/components/HoldToRecordButton.tsx <<'EOF'
import { View } from 'react-native';
import type { ChatMessage } from './MessageBubble';
export function HoldToRecordButton(_props: { chatId: string; onSent: (msg: ChatMessage) => void }) { return <View />; }
EOF

npx tsc -p apps/mobile/tsconfig.json --noEmit
TC=$?

node -e "
const fs=require('fs');
const c=fs.readFileSync('apps/mobile/src/screens/ChatScreen.tsx','utf8');
const b=fs.readFileSync('apps/mobile/src/components/MessageBubble.tsx','utf8');
const p=fs.readFileSync('apps/mobile/src/components/Composer.tsx','utf8');
if(!/export function ChatScreen/.test(c)) process.exit(2);
if(!/bubbleIncoming/.test(b)||!/bubbleOutgoing/.test(b)) process.exit(3);
if(!/HoldToRecordButton/.test(p)||!/sendBtn/.test(p)) process.exit(4);
console.log('structural OK');
"

rm -f apps/mobile/src/theme/index.ts apps/mobile/src/api/client.ts apps/mobile/src/session/AuthContext.tsx apps/mobile/src/components/AudioBubble.tsx apps/mobile/src/components/HoldToRecordButton.tsx
touch apps/mobile/src/theme/.gitkeep apps/mobile/src/api/.gitkeep apps/mobile/src/session/.gitkeep
git checkout -- apps/mobile/src/theme apps/mobile/src/api apps/mobile/src/session 2>/dev/null || true
git status --short
exit $TC
